"""Deterministic retry wrapper for migrated Meridian CRM integrations."""

from typing import Any, Callable


class TransientError(Exception):
    """A retryable transport failure."""


class PermanentError(Exception):
    """A non-retryable transport failure."""


def call_with_retry(
    endpoint_cfg: dict,
    transport: Callable[[str, int], Any],
) -> dict:
    """Invoke an injected transport using the legacy retry-count convention."""
    url = endpoint_cfg["url"]
    timeout_ms = endpoint_cfg["timeout_ms"]
    maximum_attempts = endpoint_cfg["retry"] + 1

    for attempts in range(1, maximum_attempts + 1):
        try:
            result = transport(url, timeout_ms)
        except PermanentError as exc:
            return {
                "ok": False,
                "attempts": attempts,
                "result": None,
                "error": {
                    "type": "permanent",
                    "message": str(exc),
                },
            }
        except TransientError as exc:
            if attempts == maximum_attempts:
                return {
                    "ok": False,
                    "attempts": attempts,
                    "result": None,
                    "error": {
                        "type": "transient",
                        "message": str(exc),
                    },
                }
        else:
            return {
                "ok": True,
                "attempts": attempts,
                "result": result,
                "error": None,
            }

    raise AssertionError("retry loop completed without producing an outcome")
